---@class GameDynamicConfig
local GameDynamicConfig = T(Global, "GameDynamicConfig")

---@private
function GameDynamicConfig:init()
    ---@class GameDynamicConfigData
    local config = {
        kickOutPiracyApp = false, ---是否踢掉盗版App的用户
        kickOutVersionCheckFailed = false,
        kickOutVersionCheckTimeOut = 60000,
        grayscale = {}, ---灰度配置
        minEngineVersion = {}, ---最低版本配置
    }
    self.config = config
    WebService:GetGameDynamicConfig(function(data)
        TableUtil.mergeTable(self.config, data or {})
        LogUtil.logInfo("GameDynamicConfig:init()", StringUtil.v2s(self.config))
    end)
end

---@return GameDynamicConfigData
function GameDynamicConfig:getConfig()
    return self.config
end

function GameDynamicConfig:isInGrayscale(name, userId)
    local key = DBManager:getGameType() .. "_" .. name
    local value = self.config.grayscale[key]
    if not value then
        return false
    end
    if type(value) == "number" then
        return (userId % 100) + 1 <= value
    elseif type(value) == "table" then
        return TableUtil.tableContain(value, userId)
    else
        return false
    end
end

function GameDynamicConfig:isCanEnterGame()
    local gameType = DBManager:getGameType()
    local value = self.config.minEngineVersion[gameType]
    if type(value) ~= "number" then
        return true
    end
    return EngineVersionSetting.getEngineVersion() >= value
end

GameDynamicConfig:init()